(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+wx)*0.04+t*0.5)*7 + Math.cos((y+wy)*0.03-t*0.4)*5;
  wy += Math.cos((y+wy)*0.04-t*0.45)*7 + Math.sin((x+wx)*0.035+t*0.55)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.45+1)*40, 0.14, 1.3],
    [400+Math.cos(t*0.65+2)*70, 220+Math.sin(t*0.5+4)*50, 0.11, 2.1]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const n=src.length, act=aS/n, inh=iS/n, cross=cS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.07+t*0.6)*Math.sin(sy*0.09-t*0.5)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const tw=1+Math.sin(t*0.3)*0.5;
  const spiral=(Math.sin(dist*0.05-ang*tw*3-t*1.5)+Math.sin(dist*0.04+ang*tw*4-t*1.2)+Math.sin(dist*0.08-ang*2+t*0.8)*0.5)*0.3;
  const rd = act-inh*0.7+cross*0.3+bg*0.3+spiral;
  const reaction = Math.tanh(rd*2.2);
  const sharpness = 1-Math.abs(reaction);
  const edge = Math.pow(Math.max(0,1-sharpness*8),2);
  const turing = Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx+sy)*0.15+t*0.7)*0.5+Math.sin((sx*1.5-sy*0.8)*0.1-t*0.5)*0.4;
  const cell = Math.tanh(turing*1.5)*0.3;
  const breath = 0.92+Math.sin(t*0.4)*0.08;
  const v = (reaction*0.7+cell*0.2+cross*0.1)*0.5+0.5;
  const pal = [
    [4,10,48],[10,42,88],[15,95,125],[35,160,150],
    [140,195,110],[215,185,65],[225,140,55],[195,75,60],
    [140,35,65],[60,18,58],[4,10,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum = (0.82+Math.sin(reaction*Math.PI)*0.18)*breath;
  const glow = 1+edge*0.35;
  const fl = lum*glow;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*fl)|0
  ];
}
